def add_voice(k):
  k('aria.auto.voice_unclear','Sorry, I could not hear your voice note clearly. Could you send it again or type it?','माफ़ कीजिए, आपका वॉइस नोट साफ़ सुनाई नहीं दिया। क्या आप दोबारा भेज सकते हैं या लिख सकते हैं?','ಕ್ಷಮಿಸಿ, ನಿಮ್ಮ ವಾಯ್ಸ್ ನೋಟ್ ಸ್ಪಷ್ಟವಾಗಿ ಕೇಳಿಸಲಿಲ್ಲ. ಮತ್ತೆ ಕಳುಹಿಸುತ್ತೀರಾ ಅಥವಾ ಟೈಪ್ ಮಾಡುತ್ತೀರಾ?')
  k('inbox.voice_note','Voice note','वॉइस नोट','ವಾಯ್ಸ್ ನೋಟ್')
  k('inbox.voice_heard','Heard in {{language}}','{{language}} में सुना','{{language}} ನಲ್ಲಿ ಕೇಳಿದ್ದು')
  k('inbox.voice_unsure','Orbit was not sure it heard this right','Orbit को पक्का नहीं कि सही सुना','ಸರಿಯಾಗಿ ಕೇಳಿತೆ ಎಂದು Orbit ಗೆ ಖಚಿತವಿಲ್ಲ')
  k('inbox.voice_not_heard','Could not be transcribed','लिखा नहीं जा सका','ಬರಹಕ್ಕೆ ಇಳಿಸಲಾಗಲಿಲ್ಲ')
  k('inbox.voice_play','Play voice note','वॉइस नोट चलाएँ','ವಾಯ್ಸ್ ನೋಟ್ ಪ್ಲೇ ಮಾಡಿ')
  for l,(e,h,n) in {'en':('English','अंग्रेज़ी','ಇಂಗ್ಲಿಷ್'),'hi':('Hindi','हिंदी','ಹಿಂದಿ'),'kn':('Kannada','कन्नड़','ಕನ್ನಡ'),'ta':('Tamil','तमिल','ತಮಿಳು'),'te':('Telugu','तेलुगु','ತೆಲುಗು'),'ml':('Malayalam','मलयालम','ಮಲಯಾಳಂ'),'mr':('Marathi','मराठी','ಮರಾಠಿ')}.items():
    k(f'lang.name.{l}',e,h,n)
  k('voice.recording','Listening… tap to stop','सुन रहा हूँ… रोकने के लिए टैप करें','ಕೇಳುತ್ತಿದ್ದೇನೆ… ನಿಲ್ಲಿಸಲು ಟ್ಯಾಪ್ ಮಾಡಿ')
  k('voice.transcribing','Writing down what you said…','आपकी बात लिख रहा हूँ…','ನೀವು ಹೇಳಿದ್ದನ್ನು ಬರೆಯುತ್ತಿದ್ದೇನೆ…')
  k('voice.no_mic','Allow the microphone to speak to Orbit.','Orbit से बोलने के लिए माइक्रोफ़ोन की अनुमति दें।','Orbit ಜೊತೆ ಮಾತನಾಡಲು ಮೈಕ್ರೋಫೋನ್ ಅನುಮತಿಸಿ.')
